mapper.select:
select bcipm.id,bcipm.create_time,bcipm.m_cus_batch_number_list as m_cus_batch_number
     ,bcipm.m_model,bcipm.m_model_version,bcipm.m_num_min,bcipm.m_num_max
     ,bcipm.m_score_min,bcipm.m_score_max,bcipm.m_realy_num,bcipm.m_status
from b_customer_info_push_main bcipm

    left join b_customer_info_push_batch bcipb on bcipm .id = bcipb .m_id and bcipb .is_del =1

where bcipm .m_api_code = #{mApiCode}

      and bcipm .m_status = #{mStatus}


        and bcipm .create_time >=#{pushBeginTime} 


      and bcipm .create_time <=#{pushEndTime} 


      and bcipb .m_cus_batch_number =#{cusBatchNumber}

    and bcipm .is_del =1
